:root{--bg-color:#ffffff;--text-color:#777777;--action-text-color:#000000;--header-bg-color:#e2e8f0;--pre-bg-color:#e2e8f0;--heading-text-color:#555555;--accent:#2288df;--ring:#414ddb}.dark{--bg-color:#000000;--text-color:#e2e8f0;--action-text-color:#ffffff;--header-bg-color:#15171c;--pre-bg-color:#15171c;--heading-text-color:#e2e8f0}*,::after,::before{margin:0;padding:0;box-sizing:border-box}body,html{height:100%;scroll-behavior:smooth}body{line-height:1.5;-webkit-font-smoothing:antialiased}h1,h2,h3,h4,h5,h6{font-weight:700;color:var(--text-color);margin-bottom:1rem}p{margin-bottom:1rem;color:var(--text-color);line-height:1.6}span{color:var(--text-color)}a{color:var(--accent);text-decoration:none}html{font-family:system-ui,sans-serif}.index-layout{display:grid;grid-template-areas:"main sidebar";grid-template-columns:3fr 1fr;gap:1.5rem;min-height:100vh;max-width:72rem;margin:0 auto;padding:30px 15px 65px}@media (max-width:768px){.index-layout{grid-template-areas:"main" "sidebar";grid-template-columns:1fr}}.item-layout{display:grid;grid-template-areas:"main" "sidebar";grid-template-columns:1fr;gap:1.5rem;min-height:100vh;max-width:72rem;margin:0 auto;padding:30px 15px 65px}.static_page-layout{display:grid;grid-template-areas:"main" "sidebar";grid-template-columns:1fr;gap:1.5rem;min-height:100vh;max-width:72rem;margin:0 auto;padding:30px 15px 65px}.static_page-layout>aside{display:none}img{display:block;max-width:100%;height:auto}.featured-img{padding:8px}.theme-toggle-btn{position:fixed;top:10px;right:20px;z-index:2;border:0;background:0 0;cursor:pointer;padding:0;transition:background .2s}.sun{fill:black}.moon{fill:transparent}.dark .sun{fill:transparent}.dark .moon{fill:white}nav{position:fixed;top:0;width:100%;background:var(--bg-color);z-index:2;display:flex;justify-content:space-around;align-items:center;padding:1rem 2rem}.logo{font-weight:700;font-size:1.2rem;color:var(--text-color)}nav ul{list-style:none;margin:0;padding:0}.menu{display:flex;gap:1.5rem;margin:auto}.menu a{color:var(--text-color);text-decoration:none;position:relative;padding:.25rem 0;transition:color .3s}.menu a::after{content:"";position:absolute;left:0;bottom:-2px;width:0;height:2px;background:var(--accent,#1e90ff);transition:width .3s}.menu a.active::after,.menu a:hover::after{width:100%}.menu a.active{color:var(--accent,#1e90ff);font-weight:600}#menu-toggle{display:none}.menu-icon{display:none;width:30px;height:22px;position:relative;cursor:pointer}.menu-icon span{position:absolute;height:3px;width:100%;left:0;background-color:var(--text-color);transition:.3s}.menu-icon span:first-child{top:0}.menu-icon span:nth-child(2){top:9px}.menu-icon span:nth-child(3){bottom:0}@media (max-width:768px){nav{justify-content:space-between}.logo{margin:auto}li{padding-left:var(--spacing);padding-bottom:calc(var(--spacing)/ 3)}.menu{flex-direction:column;gap:1rem;background:var(--bg-color);position:absolute;top:50px;left:0;width:100%;padding:6px 2rem;max-height:0;overflow:hidden;transition:max-height .3s ease}#menu-toggle:checked~.menu{max-height:300px}.menu-icon{display:block}#menu-toggle:checked+.menu-icon span:first-child{transform:rotate(45deg);top:9px}#menu-toggle:checked+.menu-icon span:nth-child(2){opacity:0}#menu-toggle:checked+.menu-icon span:nth-child(3){transform:rotate(-45deg);bottom:9px}}#heroSection{width:100%;margin:0;padding:0}.index-header{min-height:320px;padding-top:80px;background:linear-gradient(90deg,var(--accent),var(--ring) 70%);display:flex;align-items:center;justify-content:center}.index-header-title{font-size:3rem;font-weight:900;letter-spacing:-.03em;color:#fff;margin-bottom:1rem;text-shadow:0 2px 8px rgba(0,0,0,.08)}.index-header-gradient{background:var(--bg-color);-webkit-background-clip:text;-webkit-text-fill-color:transparent}.index-header-subtitle{font-size:1.25rem;color:#fff;opacity:.85}#heroSectionItem{min-height:120px;padding:80px 10px 0;display:flex;flex-direction:column;text-align:center}#heroSectionStaticPage{min-height:120px;padding-top:80px;display:flex;flex-direction:column;align-items:center}article.index-item{margin-bottom:20px;border:1px solid;padding:20px}div#Aside{display:flex;flex-direction:row;gap:1.5rem;flex-wrap:wrap}div#Aside>div{margin-bottom:0;margin-right:1rem;flex:1 1 330px}aside>form{padding:15px 0 20px;text-align:center}@media (max-width:768px){div#Aside{flex-direction:column;max-width:100%;min-width:0;margin-top:2rem;border-radius:0}div#Aside>div{margin-bottom:1rem;margin-right:0;box-shadow:none;border-radius:0;padding:1rem .5rem;min-width:0}}@view-transition{navigation:auto}::view-transition-group(*){animation-duration:.5s}::view-transition-old(root){animation:slide-out-to-left .5s forwards}::view-transition-new(root){animation:slide-in-from-right .5s forwards}@keyframes slide-out-to-left{from{transform:translateX(0)}to{transform:translateX(-100%)}}@keyframes slide-in-from-right{from{transform:translateX(100%)}to{transform:translateX(0)}}body{background:var(--bg-color);color:var(--text-color)}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
/*-----------------------
>>> Variable overriding
-------------------------*/
:root {
  --bg-color: #fff;
}

.dark {
  --bg-color: #000;
}

